3.1714,131.9935],[33.169,131.9933],[33.1626,131.9891],[33.1603,131.9818],[33.1571,131.983],[33.1546,131.9818],[33.1524,131.9741],[33.1536,131.9675],[33.1557,131.9663],[33.1579,131.967]],[[33.2748,131.935],[33.277,131.9341],[33.2801,131.9351],[33.281,131.937],[33.281,131.9469],[33.2817,131.9497],[33.2819,131.955],[33.281,131.9568],[33.2795,131.9576],[33.2751,131.9582],[33.2729,131.9576],[33.2718,131.956],[33.2709,131.9512],[33.2675,131.9456],[33.268,131.9439],[33.273,131.9383]]]'::jsonb;
  ring jsonb; n int; i int; j int; inside boolean;
  lat_i double precision; lng_i double precision; lat_j double precision; lng_j double precision;
begin
  for ring in select * from jsonb_array_elements(rings) loop
    n := jsonb_array_length(ring);
    inside := false;
    j := n - 1;
    for i in 0 .. n - 1 loop
      lat_i := (ring->i->>0)::double precision; lng_i := (ring->i->>1)::double precision;
      lat_j := (ring->j->>0)::double precision; lng_j := (ring->j->>1)::double precision;
      if ((lat_i > p_lat) <> (lat_j > p_lat))
         and (p_lng < (lng_j - lng_i) * (p_lat - lat_i) / (lat_j - lat_i) + lng_i) then
        inside := not inside;
      end if;
      j := i;
    end loop;
    if inside then return true; end if;
  end loop;
  return false;
end;
$$;

